import numpy as np
import copy
'''
将整体数据指定区间归一化，仅对一行数据
'''
def autoNorm(data, interval):
    max_data = max(data)
    min_data = min(data)
    min_interval = interval[0]
    max_interval = interval[1]
    if max_interval <= min_interval:
        print('设定区间后者要比前者大')
        exit()
    else:
        if max_data == min_data:
            k = 1
        else:
            k = (max_interval - min_interval)/(max_data - min_data)
    data_norm = copy.deepcopy(data)
    for i in range(len(data_norm)):
        data_norm[i] = min_interval + k * (data_norm[i] - min_data)

    # print('按设定区间{}的归一化数据为\n{}'.format(interval, data_norm))
    return data_norm


def manualNorm(data, max_data, min_data):
    # 用于data为全部数据集的一部分时，需要再获取全部数据里的最大最小值来进行归一化处理
    min_interval = min(data)
    max_interval = max(data)
    if max_interval <= min_interval:
        print('设定区间后者要比前者大')
        exit()
    else:
        if max_data != min_data:
            k = (max_interval - min_interval) / (max_data - min_data)
        else:
            # print('k=1')
            k = 1
    data_norm = copy.deepcopy(data)
    for i in range(len(data_norm)):
        data_norm[i] = min_interval + k * (data_norm[i] - min_data)

    # print('按设定区间{}的归一化数据为\n{}'.format(interval, data_norm))
    return data_norm




